  }

  invisible(votes)
}

Combining the models
ensemble_agreement()
One row per code with each model’s category and reason; a category is accepted when at least min_agreement models give it (two of three in this project).
Used in the analysis: 2. Cause of kidney failure: Agreement.


Click to show/hide R Code
# One row per code: each provider's category and reason, how many providers
# answered, whether all agree, and the accepted category. A category is
# accepted when at least `min_agreement` providers give it.
ensemble_agreement &lt;- function(votes, codes, min_agreement) {
  n_providers_total &lt;- n_distinct(votes$provider)

  top_category &lt;- votes |&gt;
    count(code, category, name = "n_agreeing") |&gt;
    slice_max(n_agreeing, n = 1, with_ties = FALSE, by = code)

  agreement &lt;- votes |&gt;
    summarize(n_providers = n(), n_categories = n_distinct(category), .by = code) |&gt;
    left_join(top_category, by = "code", relationship = "one-to-one") |&gt;
    mutate(
      unanimous = n_providers == n_providers_total & n_categories == 1,
      model_category = if_else(n_agreeing &gt;= min_agreement, category, NA_character_)
    ) |&gt;
    select(code, n_providers, n_agreeing, unanimous, model_category)

  each_provider &lt;- votes |&gt;
    select(code, provider, category, reason) |&gt;
    pivot_wider(names_from = provider, values_from = c(category, reason))

  codes |&gt;
    left_join(each_provider, by = "code", relationship = "one-to-one") |&gt;
    left_join(agreement, by = "code", relationship = "one-to-one")
}

Reporting the local models
local_model_report()
For each model that answers but does not vote: how many codes it answered once with a code from the list, how many it left unanswered, how many answers carried text that is not a code in the list, how many codes it answered more than once, and how often it gave the category the voting models accepted. Tested on synthetic answers with a known count of each.
Used in the analysis: 2. Cause of kidney failure: What the local models showed.


Click to show/hide R Code
# One row per model whose answers are reported but do not vote: how many
# codes it answered once with a code from the list, how many it left
# unanswered, how many answers carried text that is not a code in the list,
# how many codes it answered more than once, and, among codes it answered
# once that have an accepted category, how often it gave that category.
# `accepted` has one row per code with `code` and `model_category`.
local_model_report &lt;- function(votes, codes, accepted) {
  valid &lt;- semi_join(votes, codes, by = "code")
  answered_once &lt;- valid |&gt;
    filter(n() == 1, .by = c(provider, code))

  compared &lt;- answered_once |&gt;
    inner_join(
      filter(accepted, !is.na(model_category)) |&gt; select(code, model_category),
      by = "code",
      relationship = "many-to-one"
    )

  votes |&gt;
    distinct(provider) |&gt;
    left_join(count(answered_once, provider, name = "codes_answered"), by = "provider") |&gt;
    left_join(
      valid |&gt; distinct(provider, code) |&gt; count(provider, name = "codes_with_any_answer"),
      by = "provider"
    ) |&gt;
    left_join(
      anti_join(votes, codes, by = "code") |&gt; count(provider, name = "answers_not_in_list"),
      by = "provider"
    ) |&gt;
    left_join(
      valid |&gt; count(provider, code) |&gt; filter(n &gt; 1) |&gt; count(provider, name = "codes_repeated"),
      by = "provider"
    ) |&gt;
    left_join(
      compared |&gt;
        summarize(
          compared_with_accepted = n(),
          agrees_with_accepted = sum(category == model_category),
          .by = provider
        ),
      by = "provider"
    ) |&gt;
    mutate(
      across(-provider, \(n) replace_na(n, 0L)),
      codes_missing = nrow(codes) - codes_with_any_answer,
      share_agreeing = agrees_with_accepted / compared_with_accepted
    ) |&gt;
    select(
      provider, codes_answered, codes_missing, answers_not_in_list, codes_repeated,
      compared_with_accepted, agrees_with_accepted, share_agreeing
    )
}

